import * as Keychain from 'react-native-keychain';

const SERVICE = 'com.example.app.session';

export function validateCredentials(email: string, password: string): string | null {
  if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return 'Enter a valid email';
  if (password.length < 8 || password.length > 1024) return 'Use 8–1024 password characters';
  return null;
}

export async function saveCredentials(email: string, password: string): Promise<void> {
  const error = validateCredentials(email, password);
  if (error !== null) throw new Error(error);
  try {
    const result = await Keychain.setGenericPassword(email, password, {
      service: SERVICE,
      accessible: Keychain.ACCESSIBLE.WHEN_UNLOCKED_THIS_DEVICE_ONLY,
    });
    if (result === false) throw new Error('Save refused');
  } catch {
    throw new Error('Could not save credentials on this device');
  }
}

export async function clearCredentials(): Promise<void> {
  try {
    if (!await Keychain.resetGenericPassword({ service: SERVICE })) throw new Error('Clear refused');
  } catch {
    throw new Error('Could not clear credentials on this device');
  }
}

import { useRef, useState } from 'react';
import { KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { saveCredentials, validateCredentials } from '../services/storage';

export function ProfileFormScreen(): JSX.Element {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const busy = useRef(false);

  async function submit(): Promise<void> {
    if (busy.current) return;
    setSaved(false);
    const validation = validateCredentials(email.trim(), password);
    setError(validation);
    if (validation !== null) return;
    busy.current = true;
    setSaving(true);
    try {
      await saveCredentials(email.trim(), password);
      setPassword('');
      setSaved(true);
    } catch {
      setError('Could not save credentials on this device. Please retry.');
    } finally {
      busy.current = false;
      setSaving(false);
    }
  }

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView style={styles.safe} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <ScrollView contentContainerStyle={styles.form} keyboardShouldPersistTaps="handled">
          <Text>Save credentials on this device. This does not create an account.</Text>
          <TextInput
            style={styles.input}
            value={email}
            onChangeText={value => { setEmail(value); setSaved(false); setError(null); }}
            editable={!saving}
            maxLength={254}
            placeholder="Email"
            keyboardType="email-address"
            autoCapitalize="none"
            autoCorrect={false}
            accessibilityLabel="Email"
          />
          <TextInput
            style={styles.input}
            value={password}
            onChangeText={value => { setPassword(value); setSaved(false); setError(null); }}
            editable={!saving}
            maxLength={1024}
            placeholder="Password"
            secureTextEntry
            autoCapitalize="none"
            autoCorrect={false}
            accessibilityLabel="Password"
          />
          {error !== null ? <Text accessibilityRole="alert" accessibilityLiveRegion="polite">{error}</Text> : null}
          <Pressable
            style={styles.button}
            onPress={submit}
            disabled={saving}
            accessibilityRole="button"
            accessibilityState={{ disabled: saving, busy: saving }}
            accessibilityLabel="Save credentials"
          >
            <Text>{saving ? 'Saving…' : 'Save credentials'}</Text>
          </Pressable>
          {saved ? <Text accessibilityLiveRegion="polite">Credentials saved on this device.</Text> : null}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  form: { flexGrow: 1, justifyContent: 'center', padding: 24, gap: 12 },
  input: { borderWidth: 1, borderRadius: 8, padding: 12 },
  button: { borderWidth: 1, padding: 14, borderRadius: 8, alignItems: 'center' },
});
